package mz.co.aprendaacodar.course.entity;
import jakarta.persistence.*;import mz.co.aprendaacodar.common.entity.BaseEntity;
@Entity @Table(name="lesson_resources") public class LessonResource extends BaseEntity {@ManyToOne(optional=false,fetch=FetchType.LAZY) private Lesson lesson;@Column(nullable=false,length=180) private String name;@Column(columnDefinition="TEXT") private String description;@Column(nullable=false,length=500) private String fileKey;@Column(nullable=false,length=255) private String originalFileName;@Column(nullable=false,length=150) private String mimeType;@Column(nullable=false) private long fileSizeBytes;protected LessonResource(){}public LessonResource(Lesson lesson,String name,String description,String fileKey,String original,String mime,long size){this.lesson=lesson;this.name=name;this.description=description;this.fileKey=fileKey;originalFileName=original;mimeType=mime;fileSizeBytes=size;}public Lesson getLesson(){return lesson;}public String getName(){return name;}public String getDescription(){return description;}public String getFileKey(){return fileKey;}public String getOriginalFileName(){return originalFileName;}public String getMimeType(){return mimeType;}public long getFileSizeBytes(){return fileSizeBytes;}}
